  const t=i<pts.length-1?RR_EDGE_CLS.get(ids[i]<ids[i+1]?ids[i]+'_'+ids[i+1]:ids[i+1]+'_'+ids[i]):null,on=t!=null&&(t===1||t===4)===hs,xy=(pts[i][0]+ns[i][0]*o).toFixed(2)+' '+(pts[i][1]+ns[i][1]*o).toFixed(2);
