   const run=Math.max(0,timeOrdinal(t.route[i][1])-timeOrdinal(t.route[i-1][1]));
   const target=Math.max(0,Math.min(base+2,Math.round(base*(1-.65*i/Math.max(1,n-1)))+((serial+i*7)%5)-2));
